(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin(x*0.05+y*0.03+t*0.7)*5;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos(x*0.04-y*0.05-t*0.6)*5;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.14, 1.3],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+1)*40, 0.05, 2.8]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (let j = 0; j < src.length; j++) {
    const [sX, sY, f, sp] = src[j];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w = j < 6 ? 1.0 : 0.7;
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    aS2 += Math.sin(d*f*1.8 - t*sp*0.8 + 2.0) * w * 0.5;
    iS2 += Math.sin(d*f*1.3 + t*sp*0.4 + 0.8) * w * 0.5;
  }
  const n = 8;
  const act = (aS + aS2)/n, inh = (iS + iS2)/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.15)+t*0.5)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2) + Math.sin(dist*0.07-ang*5+t*0.9))*0.3;
  const cx2 = 240+Math.sin(t*0.2)*100, cy2 = 120+Math.cos(t*0.15)*80;
