  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((act*0.8 - inh + bg*0.2 + spiral2)*1.8);
  const combined = r1*0.6 + r2*0.4;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const turb = Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2)*Math.cos(sy*0.25+Math.sin(sx*0.15-t)*2)*0.15;
  const v = (combined*0.65 + cell*0.2 + turb*0.15)*0.5+0.5;
